mapper.select:
SELECT * FROM todo WHERE user_id = #{userId}
AND (due_date = #{today} OR repeat_type IS NOT NULL)
ORDER BY done ASC, importance DESC, created_at DESC

SELECT * FROM todo WHERE user_id = #{userId}
AND (due_date BETWEEN #{today} AND #{weekEnd} OR repeat_type IS NOT NULL)
ORDER BY done ASC, importance DESC, created_at DESC

SELECT * FROM todo WHERE user_id = #{userId}
AND due_date BETWEEN #{today} AND #{weekEnd} AND done = 0
ORDER BY due_date ASC, importance DESC

SELECT * FROM todo WHERE user_id = #{userId}
AND due_date IS NOT NULL AND due_date < #{today} AND done = 0
ORDER BY due_date ASC, importance DESC

mapper.update:
UPDATE todo SET title = #{title}, content = #{content}, description = #{description}, importance = #{importance},
repeat_type = #{repeatType}, repeat_config = #{repeatConfig},
repeat_end_type = #{repeatEndType}, repeat_end_value = #{repeatEndValue},
due_date = #{dueDate}, updated_at = #{updatedAt}
WHERE id = #{id}
